def make(n):
    result = []
    for _ in range(n % 8 + 1):
        args = []
        # seed‑based deterministic choices for version strings
        i = _ % 10
        if i == 0:
            v = "1.2.3"
        elif i == 1:
            v = "0.0.1"
        elif i == 2:
            v = "10.20.30"
        elif i == 3:
            v = "1.0.0-alpha"
        elif i == 4:
            v = "2.3.4+build"
        elif i == 5:
            v = "1.2.3.dev1"
        elif i == 6:
            v = "1.2.3rc1"
        elif i == 7:
            v = "1.2.3.post1"
        else:
            v = "1.2.3"
        args.append([v])
        result.append(args)
    return result

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append('9' * i)
    version = '.'.join(chunks) + 'c5'
    return [(version,)]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    version = '.'.join(chunks) + 'c5'
    return [(version,)]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append('9' * i)
    version = '.'.join(chunks) + '-alpha.1'
    return [(version,)]

def make(n):
    inner = [''] * (n-1)
    for idx in range(n-1):
        filler = '#'
        inner[idx] = filler * ((idx+1)%4 + 1)
    nums = [str(j%10) for j in range(n)]
    comps = []
    for j in range(len(nums)):
        comps.append(nums[j])
        if j < len(inner):
            comps.append(inner[j])
    body = ''.join(comps)
    full = body[::-1].lower() + '+local.build.with.many.dots'
    return [(full,)]}]}
